import { useState } from "react";

import { Example, SectionPage, Specimen } from "../kit.js";

import { Calendar, addDays, todayIso, type DateRange, type IsoDate } from "../../ui/date-picker/index.js";

const today = todayIso();

function SingleCalendar() {
    const [value, setValue] = useState<IsoDate | null>(addDays(today, 3));
    return (<Example label={value ?? "Nothing picked"}>
      <div className="glass-overlay fa-popup fa-popover fa-popover-preview fa-date-popover" data-size="sm">
        <div className="fa-popover-body">
          <Calendar value={value} onValueChange={setValue} aria-label="Maintenance day"/>
        </div>
      </div>
    </Example>);
}

function RangeCalendar() {
    const [value, setValue] = useState<DateRange | null>({ start: addDays(today, -9), end: addDays(today, -2) });
    return (<Example label={value ? `${value.start} – ${value.end}` : "Nothing picked"}>
      <div className="glass-overlay fa-popup fa-popover fa-popover-preview fa-date-popover" data-size="sm">
        <div className="fa-popover-body">
          <Calendar mode="range" value={value} onValueChange={setValue} aria-label="Reporting period"/>
        </div>
      </div>
    </Example>);
}

export default function DatePickerSection() {
    return (<SectionPage>
      <Specimen title="Calendar" description="Arrow keys move by day and week, Home and End to the week's ends, Page Up and Page Down by month (Shift: year), Enter picks. In a range, the first pick is the start; the band follows the pointer until the second.">
        <SingleCalendar />
        <RangeCalendar />
        <Example label="Bounded: the next 30 days">
          <div className="glass-overlay fa-popup fa-popover fa-popover-preview fa-date-popover" data-size="sm">
            <div className="fa-popover-body">
              <Calendar min={today} max={addDays(today, 30)} aria-label="Next 30 days"/>
            </div>
          </div>
        </Example>
      </Specimen>

      <></>

      <></>

      <></>

      <></>

      <></>

      <></>
    </SectionPage>);
}
